r=Path(__file__).resolve().parents[1];o=r/'outputs/experiment3';m=json.loads((o/'temporal_metrics.json').read_text());a=json.loads((o/'supervised_audit.json').read_text());b=json.loads((r/'outputs/experiment2/baselines.json').read_text());tiny=json.loads((o/'tiny_batch.json').read_text())
